tools.example:
set_property PACKAGE_PIN AH11 [get_ports sys_clk_p]
set_property IOSTANDARD DIFF_SSTL12 [get_ports sys_clk_p]

# Whole bus in a loop
set pins {H17 K15 J13 N14}
for {set i 0} {$i < 4} {incr i} {
  set_property PACKAGE_PIN [lindex $pins $i] [get_ports led[$i]]
  set_property IOSTANDARD LVCMOS33 [get_ports led[$i]]
}

set_property IOSTANDARD LVCMOS33 [get_ports -filter {DIRECTION == OUT && NAME =~ led*}]

# Apply the same input delay to a whole bus
set_input_delay -clock rx_clk -max 3.2 [get_ports {rxd[*]}]

# Audit: which ports still have no package pin?
foreach p [get_ports] {
  if {[get_property PACKAGE_PIN $p] eq ""} { puts "unlocated: $p" }
}
